public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    int[][] grid = new int[n][n];
    for (int[] path : paths) {
        grid[path[0]][path[1]] = 1;
        grid[path[1]][path[0]] = 1;
    }

    boolean[] visited = new boolean[n * n];
    boolean canTravel = dfs(grid, start[0] * n + start[1], end[0] * n + end[1], visited);
    return canTravel ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int[][] grid, int current, int end, boolean[] visited) {
    if (current == end) {
        return true;
    }

    int row = current / grid.length;
    int col = current % grid.length;
    visited[current] = true;

    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[row][col] == 1 && !visited[i * grid.length + j]) {
                if (dfs(grid, i * grid.length + j, end, visited)) {
                    return true;
                }
            }
        }
    }

    visited[current] = false;
    return false;
}
