import java.util.*;

public class MinTimeToCollectApples {

    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        // Create an adjacency list to represent the tree
        List<List<Integer>> adjList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adjList.add(new ArrayList<>());
        }

        // Build the adjacency list
        for (int[] edge : edges) {
            adjList.get(edge[0]).add(edge[1]);
            adjList.get(edge[1]).add(edge[0]);
        }

        // Use a boolean array to keep track of visited nodes to avoid processing the same node multiple times
        boolean[] visited = new boolean[n];

        // Start the DFS traversal from node 0
        return dfs(0, adjList, hasApple, visited) * 2; // Each edge traversal counts as 2 units of time
    }

    // Helper method to perform DFS and calculate the time
    private int dfs(int node, List<List<Integer>> adjList, boolean[] hasApple, boolean[] visited) {
        // Mark the current node as visited
        visited[node] = true;
        int time = 0;

        // Traverse all adjacent nodes
        for (int neighbor : adjList.get(node)) {
            if (!visited[neighbor]) {
                // Recursively call DFS for the neighbor
                int neighborTime = dfs(neighbor, adjList, hasApple, visited);

                // If the neighbor has an apple or its subtree has apples, add the time spent to traverse to/from the neighbor
                if (neighborTime > 0 || hasApple[neighbor]) {
                    time += neighborTime + 2; // Each edge traversal counts as 2 units of time
                }
            }
        }

        return time;
    }

    public static void main(String[] args) {
        MinTimeToCollectApples solution = new MinTimeToCollectApples();

        // Test case 1
        int n1 = 7;
        int[][] edges1 = {{0,1}, {0,2}, {1,4}, {1,5}, {2,3}, {2,6}};
        boolean[] hasApple1 = {false, false, true, false, true, true, false};
