public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int n = A.length;
    boolean[] visited = new boolean[n];
    int count = 0;

    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            visited[i] = true;
            count += backtrack(A, i, 1, visited);
            visited[i] = false;
        }
    }

    return count;
}

private static int backtrack(int[] A, int index, int length, boolean[] visited) {
    if (length == A.length) {
        return 1;
    }

    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (!visited[i] && isPerfectSquare(A[index] + A[i])) {
            visited[i] = true;
            count += backtrack(A, i, length + 1, visited);
            visited[i] = false;
        }
    }

    return count;
}

private static boolean isPerfectSquare(int num) {
    if (num < 0) {
        return false;
    }
    int sqrt = (int) Math.round(Math.sqrt(num));
    return sqrt * sqrt == num;
}
