public static int[] diagonalOrder(int[][] mat) {
    if (mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    for (int k = 0; k < rows + cols - 1; k++) {
        if (k % 2 == 0) {
            // Traverse from top to bottom
            int i = Math.min(k, rows - 1);
            int j = k - i;
            while (i >= 0 && j < cols) {
                result[index++] = mat[i][j];
                i--;
                j++;
            }
        } else {
            // Traverse from bottom to top
            int i = k < cols ? 0 : k - cols + 1;
            int j = Math.min(k, cols - 1);
            while (j >= 0 && i < rows) {
                result[index++] = mat[i][j];
                i++;
                j--;
            }
        }
    }

    return result;
}
